/// <summary>
/// CB167_PerformStockReservation
/// This is a service class for sales order guide check.
/// </summary>
class METSalesOrderGuideCheckService extends METSysOperationService
{
    private METSalesOrderGuideCheckContract contract;
    private guid topPickingProcessId;

}

Method.Source:
// <summary>
/// Returns task service class name.
/// </summary>
/// <returns>Task service class name</returns>
protected str getTaskServiceClass()
{
    return classStr(METSalesOrderGuideCheckTaskService);
}

/// <summary>
/// Returns task service class method.
/// </summary>
/// <returns>Task service class method</returns>
protected str getTaskServiceClassMethod()
{
    return methodStr(METSalesOrderGuideCheckTaskService, process);
}

/// <summary>
/// Returns caption of the task service class.
/// </summary>
/// <returns>Task service class caption</returns>
protected str getTaskServiceCaption()
{
    return "@MET:SalesOrderGuideCheck";
}

/// <summary>
/// Executes the main process.
/// </summary>
/// <param name = "_contract">
/// <c>METSalesOrderGuideCheckContract</c>
/// </param>
public void process(METSalesOrderGuideCheckContract _contract)
{
    this.processInternal(_contract);
}

/// <summary>
/// Initialise global variables.
/// </summary>
public void initialise()
{
    super();

    this.stageDataIntoQueue();
}

/// <summary>
/// Stages data int table <c>METSalesOrderGuideCheckContract</c>.
/// </summary>
void stageDataIntoQueue()
{
    #OCCRetryCount

    METSalesOrderGuideCheckQueue salesOrderGuideCheckQueue;
    SalesLine                    salesLine;
    METSalesLine                 metSalesLine;
    SalesId                      salesId;

    contract            = dataContract as METSalesOrderGuideCheckContract;
    topPickingProcessId = newGuid();
    salesId             = contract.parmSalesId();

    try
    {
        ttsbegin;

        METSalesOrderGuideCheckQueue::cleanUpSalesOrderGuideCheckQueue();

        insert_recordset salesOrderGuideCheckQueue(ProcessId, SalesLine, ReasonId)
            select topPickingProcessId, RecId  from salesLine
                where (!salesId || (salesId && salesLine.SalesId == salesId))
                    &&  salesLine.SalesStatus == SalesStatus::Backorder
                join ReasonId from metSalesLine
                    where metSalesLine.SalesLine == salesLine.RecId
                    &&  (metSalesLine.ReasonId == METConstants::NIRReasonCode
                    ||   metSalesLine.ReasonId == METConstants::NewReasonCode);

        ttscommit;

    }
    catch (Exception::Deadlock)
    {
        if (xSession::currentRetryCount() >= #RetryNum)
        {
            throw Exception::Deadlock;
        }
        else
        {
            retry;
        }
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
    catch (Exception::Error)
    {
        // catch the errors so processing can continue
        curext(); // avoids a warning about an empty block
    }
}

/// <summary>
/// Initializes the task data contract.
/// </summary>
/// <param name = "_taskDataContract">task data contract</param>
protected void initTaskDataContract(METSysOperationTaskDataContract _taskDataContract)
{
    super(_taskDataContract);
    contract = _taskDataContract as METSalesOrderGuideCheckContract;
    contract.parmTopPickingProcessId(topPickingProcessId);
}

/// <summary>
/// Provides task data contract.
/// </summary>
/// <returns>task data contract</returns>
protected METSysOperationTaskDataContract taskDataContractObject()
{
    return new METSalesOrderGuideCheckContract();
}
